"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[128],{85:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-01-tools-data</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-1-инструменты-данные-и-первый-ориентир">Лабораторная\nработа 1. Инструменты, данные и первый ориентир</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>первое занятие курса, <strong>до</strong> лекции 1</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>нет — работа опирается только на линейную алгебру и матанализ</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–4) + 4 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Научиться приводить сырую таблицу к виду, пригодному для обучения\nмодели: определять типы признаков, находить и исправлять дефекты данных,\nразделять выборку на обучающую и контрольную <strong>до</strong> любой\nобработки и строить ориентир (baseline), с которым дальше сравниваются\nвсе модели курса.</p>\n<p>Отдельная цель — освоить векторизованные вычисления в NumPy: весь\nкурс написан в матричной записи, и все реализации «с нуля» в работах 2–9\nопираются на приёмы из части 1.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab01_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<h2 id="как-устроен-практикум">Как устроен практикум</h2>\n<p>Практикум состоит из 9 работ и <strong>чередуется</strong> с\nлекциями:</p>\n<pre><code>Лаб 1 → Лек 1 → Лаб 2 → Лек 2 → … → Лек 8 → Лаб 9</code></pre>\n<p>Поэтому каждая лабораторная опирается на <strong>уже\nпрочитанные</strong> лекции: работа\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">k+1</annotation></semantics></math>\nзакрепляет лекцию\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>.\nТекущая работа идёт первой, до лекции 1, и никакой теории курса ещё не\nтребует — это подготовка инструментов и данных.</p>\n<p>Правила оформления:</p>\n<ul>\n<li>ноутбук должен исполняться сверху вниз в свежем ядре (Kernel →\nRestart &amp; Run All);</li>\n<li>каждое число, попавшее в вывод, должно быть воспроизводимым —\nфиксируйте <code>random_state</code>;</li>\n<li>графики без подписей осей не засчитываются;</li>\n<li>ячейка <strong>Вывод</strong> — обязательная часть задания, а не\nукрашение.</li>\n</ul>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb2-7"><a href="#cb2-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-8"><a href="#cb2-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb2-9"><a href="#cb2-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-10"><a href="#cb2-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb2-11"><a href="#cb2-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb2-12"><a href="#cb2-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb2-13"><a href="#cb2-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-14"><a href="#cb2-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-15"><a href="#cb2-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb2-16"><a href="#cb2-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb2-17"><a href="#cb2-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb2-18"><a href="#cb2-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb2-19"><a href="#cb2-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb2-20"><a href="#cb2-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb2-21"><a href="#cb2-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb2-22"><a href="#cb2-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb2-23"><a href="#cb2-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb2-24"><a href="#cb2-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb2-25"><a href="#cb2-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb2-26"><a href="#cb2-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-27"><a href="#cb2-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-28"><a href="#cb2-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb2-29"><a href="#cb2-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb2-30"><a href="#cb2-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-31"><a href="#cb2-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb2-32"><a href="#cb2-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb2-33"><a href="#cb2-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-34"><a href="#cb2-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb2-35"><a href="#cb2-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb2-36"><a href="#cb2-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb2-37"><a href="#cb2-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb2-38"><a href="#cb2-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb2-39"><a href="#cb2-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb2-40"><a href="#cb2-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb2-41"><a href="#cb2-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb2-42"><a href="#cb2-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb2-43"><a href="#cb2-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-44"><a href="#cb2-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb2-45"><a href="#cb2-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-46"><a href="#cb2-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> make_table</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-numpy-векторизация-вместо-циклов">Часть 1. NumPy:\nвекторизация вместо циклов</h1>\n<p>Весь курс записан в матричных обозначениях. Матрица\n«объекты–признаки»</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>F</mi><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><mo stretchy="false" form="postfix">∥</mo><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><msub><mo stretchy="false" form="postfix">∥</mo><mrow><mi>ℓ</mi><mo>×</mo><mi>n</mi></mrow></msub><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><mrow><mo stretchy="true" form="prefix">(</mo><mtable><mtr><mtd columnalign="center" style="text-align: center"><msub><mi>f</mi><mn>1</mn></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mn>1</mn></msub><mo stretchy="false" form="postfix">)</mo></mtd><mtd columnalign="center" style="text-align: center"><mi>…</mi></mtd><mtd columnalign="center" style="text-align: center"><msub><mi>f</mi><mi>n</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mn>1</mn></msub><mo stretchy="false" form="postfix">)</mo></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><mi>⋮</mi></mtd><mtd columnalign="center" style="text-align: center"><mo>⋱</mo></mtd><mtd columnalign="center" style="text-align: center"><mi>⋮</mi></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><msub><mi>f</mi><mn>1</mn></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>ℓ</mi></msub><mo stretchy="false" form="postfix">)</mo></mtd><mtd columnalign="center" style="text-align: center"><mi>…</mi></mtd><mtd columnalign="center" style="text-align: center"><msub><mi>f</mi><mi>n</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>ℓ</mi></msub><mo stretchy="false" form="postfix">)</mo></mtd></mtr></mtable><mo stretchy="true" form="postfix">)</mo></mrow><mo>,</mo></mrow><annotation encoding="application/x-tex">\nF \\;=\\; \\|f_j(x_i)\\|_{\\ell \\times n} \\;=\\;\n\\begin{pmatrix}\nf_1(x_1) &amp; \\dots &amp; f_n(x_1)\\\\\n\\vdots &amp; \\ddots &amp; \\vdots\\\\\nf_1(x_\\ell) &amp; \\dots &amp; f_n(x_\\ell)\n\\end{pmatrix},\n</annotation></semantics></math></p>\n<p>где\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\n— число объектов,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>n</mi><annotation encoding="application/x-tex">n</annotation></semantics></math>\n— число признаков. В NumPy это массив формы <code>(l, n)</code>.\nПравило, которое сэкономит вам десятки часов за курс: <strong>если вы\nпишете цикл <code>for</code> по объектам выборки — почти наверняка есть\nвекторизованная запись, которая короче и в десятки раз\nбыстрее.</strong></p>\n</div>\n<div id="cell006" class="cell markdown">\n<h3 id="задание-11-попарные-расстояния">Задание 1.1. Попарные\nрасстояния</h3>\n<p>Даны две матрицы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>∈</mo><msup><mi>ℝ</mi><mrow><mi>m</mi><mo>×</mo><mi>n</mi></mrow></msup></mrow><annotation encoding="application/x-tex">A \\in \\mathbb{R}^{m \\times n}</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>∈</mo><msup><mi>ℝ</mi><mrow><mi>k</mi><mo>×</mo><mi>n</mi></mrow></msup></mrow><annotation encoding="application/x-tex">B \\in \\mathbb{R}^{k \\times n}</annotation></semantics></math>\n(строки — объекты). Требуется матрица квадратов евклидовых расстояний\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>D</mi><mo>∈</mo><msup><mi>ℝ</mi><mrow><mi>m</mi><mo>×</mo><mi>k</mi></mrow></msup></mrow><annotation encoding="application/x-tex">D \\in \\mathbb{R}^{m \\times k}</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>D</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><msub><mi>a</mi><mi>i</mi></msub><mo>−</mo><msub><mi>b</mi><mi>j</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">D_{ij} = \\|a_i - b_j\\|^2</annotation></semantics></math>.</p>\n<p>Реализуйте два способа и сравните их по времени и по результату:</p>\n<ol>\n<li>двойной цикл по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>i</mi><annotation encoding="application/x-tex">i</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>j</mi><annotation encoding="application/x-tex">j</annotation></semantics></math>;</li>\n<li>векторизованно, по тождеству\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>a</mi><mo>−</mo><mi>b</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>a</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>−</mo><mn>2</mn><mo stretchy="false" form="prefix">⟨</mo><mi>a</mi><mo>,</mo><mi>b</mi><mo stretchy="false" form="postfix">⟩</mo><mi>+</mi><mo stretchy="false" form="postfix">∥</mo><mi>b</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\|a - b\\|^2 = \\|a\\|^2 - 2\\langle a, b\\rangle + \\|b\\|^2</annotation></semantics></math>.</li>\n</ol>\n<p>Эта функция понадобится в работе 7 (метрические методы), поэтому\nнапишите её аккуратно.</p>\n</div>\n<div id="cell007" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> time</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> dists_loops(A, B):</span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Попарные квадраты расстояний двойным циклом (эталон корректности).&quot;&quot;&quot;</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте через два вложенных цикла</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> dists_vectorized(A, B):</span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;То же самое без циклов: ||a||^2 - 2&lt;a,b&gt; + ||b||^2.&quot;&quot;&quot;</span></span>\n<span id="cb4-12"><a href="#cb4-12" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте без единого цикла (подсказка: broadcasting и A @ B.T)</span></span>\n<span id="cb4-13"><a href="#cb4-13" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-14"><a href="#cb4-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-15"><a href="#cb4-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-16"><a href="#cb4-16" aria-hidden="true" tabindex="-1"></a>A <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">400</span>, <span class="dv">20</span>))</span>\n<span id="cb4-17"><a href="#cb4-17" aria-hidden="true" tabindex="-1"></a>B <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">300</span>, <span class="dv">20</span>))</span>\n<span id="cb4-18"><a href="#cb4-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-19"><a href="#cb4-19" aria-hidden="true" tabindex="-1"></a>t0 <span class="op">=</span> time.perf_counter()<span class="op">;</span> D_loop <span class="op">=</span> dists_loops(A, B)<span class="op">;</span> t_loop <span class="op">=</span> time.perf_counter() <span class="op">-</span> t0</span>\n<span id="cb4-20"><a href="#cb4-20" aria-hidden="true" tabindex="-1"></a>t0 <span class="op">=</span> time.perf_counter()<span class="op">;</span> D_vec <span class="op">=</span> dists_vectorized(A, B)<span class="op">;</span> t_vec <span class="op">=</span> time.perf_counter() <span class="op">-</span> t0</span>\n<span id="cb4-21"><a href="#cb4-21" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-22"><a href="#cb4-22" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;максимальное расхождение: </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">abs</span>(D_loop <span class="op">-</span> D_vec)<span class="sc">.</span><span class="bu">max</span>()<span class="sc">:.2e}</span><span class="ss">&quot;</span>)</span>\n<span id="cb4-23"><a href="#cb4-23" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;цикл          : </span><span class="sc">{</span>t_loop<span class="op">*</span><span class="dv">1000</span><span class="sc">:8.1f}</span><span class="ss"> мс&quot;</span>)</span>\n<span id="cb4-24"><a href="#cb4-24" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;векторизация  : </span><span class="sc">{</span>t_vec<span class="op">*</span><span class="dv">1000</span><span class="sc">:8.1f}</span><span class="ss"> мс&quot;</span>)</span>\n<span id="cb4-25"><a href="#cb4-25" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;ускорение     : </span><span class="sc">{</span>t_loop<span class="op">/</span>t_vec<span class="sc">:8.1f}</span><span class="ss"> раз&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Во сколько раз векторизация быстрее? Почему\nрасхождение не равно строго нулю и почему в векторизованной версии стоит\n<code>np.maximum(D, 0)</code>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell009" class="cell markdown">\n<h3 id="задание-12-broadcasting-стандартизация-вручную">Задание 1.2.\nBroadcasting: стандартизация вручную</h3>\n<p>Стандартизация признака — вычитание среднего и деление на стандартное\nотклонение:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mover><mi>f</mi><mo accent="true">̃</mo></mover><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mrow><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mover><msub><mi>f</mi><mi>j</mi></msub><mo accent="true">¯</mo></mover></mrow><msub><mi>σ</mi><mi>j</mi></msub></mfrac><mo>,</mo><mspace width="2.0em"></mspace><mover><msub><mi>f</mi><mi>j</mi></msub><mo accent="true">¯</mo></mover><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mspace width="2.0em"></mspace><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mover><msub><mi>f</mi><mi>j</mi></msub><mo accent="true">¯</mo></mover><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\tilde f_j(x_i) = \\frac{f_j(x_i) - \\overline{f_j}}{\\sigma_j},\n\\qquad\n\\overline{f_j} = \\frac1\\ell \\sum_{i=1}^{\\ell} f_j(x_i),\n\\qquad\n\\sigma_j^2 = \\frac1\\ell \\sum_{i=1}^{\\ell} \\bigl(f_j(x_i) - \\overline{f_j}\\bigr)^2 .\n</annotation></semantics></math></p>\n<p>Реализуйте её одной строкой на broadcasting&#39;е (без циклов) и\nпроверьте, что у результата нулевые средние и единичные дисперсии по\nстолбцам.</p>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>X <span class="op">=</span> rng.normal(loc<span class="op">=</span>[<span class="fl">10.0</span>, <span class="op">-</span><span class="fl">3.0</span>, <span class="fl">100.0</span>], scale<span class="op">=</span>[<span class="fl">2.0</span>, <span class="fl">0.5</span>, <span class="fl">25.0</span>], size<span class="op">=</span>(<span class="dv">500</span>, <span class="dv">3</span>))</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: вычислите mean и std по столбцам и стандартизуйте X без циклов</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>mean <span class="op">=</span> ...</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>std <span class="op">=</span> ...</span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>X_std <span class="op">=</span> ...</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;средние до :&quot;</span>, np.<span class="bu">round</span>(mean, <span class="dv">3</span>))</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;средние после:&quot;</span>, np.<span class="bu">round</span>(X_std.mean(axis<span class="op">=</span><span class="dv">0</span>), <span class="dv">12</span>))</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;ст. откл. после:&quot;</span>, np.<span class="bu">round</span>(X_std.std(axis<span class="op">=</span><span class="dv">0</span>), <span class="dv">12</span>))</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a><span class="cf">assert</span> np.allclose(X_std.mean(axis<span class="op">=</span><span class="dv">0</span>), <span class="dv">0</span>, atol<span class="op">=</span><span class="fl">1e-10</span>)</span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a><span class="cf">assert</span> np.allclose(X_std.std(axis<span class="op">=</span><span class="dv">0</span>), <span class="dv">1</span>, atol<span class="op">=</span><span class="fl">1e-10</span>)</span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;OK&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<hr />\n<h1 id="часть-2-индивидуальная-выборка-первичный-осмотр">Часть 2.\nИндивидуальная выборка: первичный осмотр</h1>\n<p>Таблица генерируется по вашему варианту. Она сознательно «грязная» —\nпримерно такой вид имеют данные, которые приходят из реальной\nинформационной системы.</p>\n<p>Ваша задача в частях 2–7 — превратить её в матрицу\n«объекты–признаки», пригодную для обучения, и <strong>честно</strong>\nоценить, сколько информации в ней есть.</p>\n</div>\n<div id="cell012" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>df_raw, meta <span class="op">=</span> make_table(variant)</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>TASK <span class="op">=</span> meta[<span class="st">&quot;task&quot;</span>]          <span class="co"># &#39;regression&#39; или &#39;classification&#39;</span></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>TARGET <span class="op">=</span> meta[<span class="st">&quot;target&quot;</span>]      <span class="co"># имя целевого столбца</span></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;предметная область : </span><span class="sc">{</span>meta[<span class="st">&#39;domain&#39;</span>]<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;тип задачи         : </span><span class="sc">{</span>TASK<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;целевая переменная : </span><span class="sc">{</span>TARGET<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;размер таблицы     : </span><span class="sc">{</span>df_raw<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss"> объектов x </span><span class="sc">{</span>df_raw<span class="sc">.</span>shape[<span class="dv">1</span>] <span class="op">-</span> <span class="dv">1</span><span class="sc">}</span><span class="ss"> признаков&quot;</span>)</span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>df_raw.head(<span class="dv">8</span>)</span></code></pre></div>\n</div>\n<div id="cell013" class="cell markdown">\n<h3 id="задание-21-что-вообще-лежит-в-таблице">Задание 2.1. Что вообще\nлежит в таблице</h3>\n<p>Выведите: типы столбцов (<code>dtypes</code>), число уникальных\nзначений в каждом столбце, описательные статистики\n(<code>describe</code>) отдельно для числовых и для нечисловых\nстолбцов.</p>\n<p>Обратите внимание на столбцы, тип которых <code>object</code>, хотя\nпо смыслу они числовые, — это первое, что придётся чинить.</p>\n</div>\n<div id="cell014" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: соберите сводную таблицу: тип, число уникальных значений, число и доля</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="co"># пропусков, пример значения — по каждому столбцу.</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>info <span class="op">=</span> ...</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>display(info)</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: describe() отдельно для числовых и для object-столбцов</span></span></code></pre></div>\n</div>\n<div id="cell015" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какие столбцы прочитаны как\n<code>object</code>, хотя по смыслу числовые? Какие столбцы выглядят\nбесполезными уже сейчас?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell016" class="cell markdown">\n<hr />\n<h1 id="часть-3-типы-признаков-и-приведение-типов">Часть 3. Типы\nпризнаков и приведение типов</h1>\n<p>Признак — это отображение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>f</mi><mo>:</mo><mi>X</mi><mo>→</mo><msub><mi>D</mi><mi>f</mi></msub></mrow><annotation encoding="application/x-tex">f: X \\to D_f</annotation></semantics></math>,\nи от множества\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>D</mi><mi>f</mi></msub><annotation encoding="application/x-tex">D_f</annotation></semantics></math>\nзависит, что с признаком вообще можно делать:</p>\n<table>\n<colgroup>\n<col style="width: 25%" />\n<col style="width: 25%" />\n<col style="width: 25%" />\n<col style="width: 25%" />\n</colgroup>\n<thead>\n<tr>\n<th>Тип</th>\n<th><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>D</mi><mi>f</mi></msub><annotation encoding="application/x-tex">D_f</annotation></semantics></math></th>\n<th>Пример</th>\n<th>Что осмысленно</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>бинарный</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">{</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\{0, 1\\}</annotation></semantics></math></td>\n<td>«есть балкон»</td>\n<td>всё</td>\n</tr>\n<tr>\n<td>номинальный</td>\n<td>конечное, без порядка</td>\n<td>«район»</td>\n<td>сравнение на равенство</td>\n</tr>\n<tr>\n<td>порядковый</td>\n<td>конечное, упорядоченное</td>\n<td>«ремонт: без / косметический / евро»</td>\n<td>сравнение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mo>≤</mo><annotation encoding="application/x-tex">\\le</annotation></semantics></math></td>\n</tr>\n<tr>\n<td>количественный</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℝ</mi><annotation encoding="application/x-tex">\\mathbb{R}</annotation></semantics></math></td>\n<td>«площадь»</td>\n<td>арифметика</td>\n</tr>\n</tbody>\n</table>\n<p>Ошибка кодирования здесь стоит дорого: если номинальный признак\n«район» закодировать числами 1..5, модель решит, что «Юг»\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mo>&gt;</mo><annotation encoding="application/x-tex">&gt;</annotation></semantics></math>\n«Север» и что «Запад» ровно посередине между ними.</p>\n</div>\n<div id="cell017" class="cell markdown">\n<h3 id="задание-31-починить-типы">Задание 3.1. Починить типы</h3>\n<p>Напишите функцию <code>to_numeric_safe(s)</code>, которая пытается\nпревратить столбец-строку в числовой: убирает пробелы-разделители\nразрядов, заменяет запятую на точку и приводит к <code>float</code>.\nЕсли после этого больше 20 % значений не распарсились — столбец\nдействительно нечисловой, возвращаем его как есть.</p>\n<p>Примените её ко всем <code>object</code>-столбцам.</p>\n</div>\n<div id="cell018" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> to_numeric_safe(s: pd.Series, threshold: <span class="bu">float</span> <span class="op">=</span> <span class="fl">0.2</span>) <span class="op">-&gt;</span> pd.Series:</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Строковый столбец -&gt; числовой, если он на самом деле числовой.&quot;&quot;&quot;</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: снять пробелы-разделители, заменить &#39;,&#39; на &#39;.&#39;, привести к числу.</span></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>    <span class="co"># Если доля непреобразованных непустых значений &gt; threshold — вернуть s без изменений.</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> df_raw.copy()</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> df.columns:</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>    before <span class="op">=</span> df[col].dtype</span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>    df[col] <span class="op">=</span> to_numeric_safe(df[col])</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a>    <span class="cf">if</span> before <span class="op">!=</span> df[col].dtype:</span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a>        <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>col<span class="sc">:28s}</span><span class="ss">: </span><span class="sc">{</span>before<span class="sc">}</span><span class="ss"> -&gt; </span><span class="sc">{</span>df[col]<span class="sc">.</span>dtype<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-15"><a href="#cb8-15" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;</span><span class="ch">\\n</span><span class="st">Типы после приведения:&quot;</span>)</span>\n<span id="cb8-16"><a href="#cb8-16" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(df.dtypes.value_counts())</span></code></pre></div>\n</div>\n<div id="cell019" class="cell markdown">\n<h3 id="задание-32-нормализация-категорий">Задание 3.2. Нормализация\nкатегорий</h3>\n<p>В категориальных столбцах одно и то же значение встречается в разных\nнаписаниях (<code>&#39;Москва&#39;</code>, <code>&#39;москва &#39;</code>,\n<code>&#39;МОСКВА&#39;</code>). Для компьютера это три разные категории.</p>\n<p>Приведите категориальные столбцы к каноническому виду и сравните\nчисло уникальных значений до и после.</p>\n</div>\n<div id="cell020" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a>cat_cols <span class="op">=</span> meta[<span class="st">&quot;categorical&quot;</span>]</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;до нормализации:&quot;</span>)</span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> cat_cols:</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;  </span><span class="sc">{</span>col<span class="sc">:22s}</span><span class="ss">: </span><span class="sc">{</span>df[col]<span class="sc">.</span>nunique()<span class="sc">}</span><span class="ss"> значений -&gt; </span><span class="sc">{</span><span class="bu">sorted</span>(df[col].dropna().unique())[:<span class="dv">6</span>]<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: привести строковые значения к нижнему регистру и убрать краевые пробелы.</span></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a><span class="co"># Осторожно: пропуски (NaN) не являются строками.</span></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;</span><span class="ch">\\n</span><span class="st">после нормализации:&quot;</span>)</span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> cat_cols:</span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;  </span><span class="sc">{</span>col<span class="sc">:22s}</span><span class="ss">: </span><span class="sc">{</span>df[col]<span class="sc">.</span>nunique()<span class="sc">}</span><span class="ss"> значений -&gt; </span><span class="sc">{</span><span class="bu">sorted</span>(df[col].dropna().unique())<span class="sc">}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell021" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Во сколько раз сократилось число категорий?\nЧто случилось бы с One-Hot кодированием, если бы вы этот шаг\nпропустили?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell022" class="cell markdown">\n<hr />\n<h1 id="часть-4-дефекты-данных">Часть 4. Дефекты данных</h1>\n<p>Разберём четыре типовых дефекта: дубликаты, вырожденные признаки,\nпропуски и выбросы.</p>\n</div>\n<div id="cell023" class="cell markdown">\n<h3 id="задание-41-дубликаты-и-вырожденные-признаки">Задание 4.1.\nДубликаты и вырожденные признаки</h3>\n<p>Найдите полные дубликаты строк и удалите их. Найдите признаки с одним\nуникальным значением (нулевая дисперсия) и признаки, у которых доля\nсамого частого значения превышает 99 %, — они не несут информации о\nразличиях между объектами.</p>\n</div>\n<div id="cell024" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: посчитайте и удалите полные дубликаты строк</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a>n_dup <span class="op">=</span> ...</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;полных дубликатов строк: </span><span class="sc">{</span>n_dup<span class="sc">}</span><span class="ss"> (</span><span class="sc">{</span>n_dup <span class="op">/</span> <span class="bu">len</span>(df) <span class="op">*</span> <span class="dv">100</span><span class="sc">:.1f}</span><span class="ss"> %)&quot;</span>)</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: найдите константные и почти константные (доля моды &gt; 0.99) признаки,</span></span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a><span class="co"># не трогая целевую переменную, и удалите их</span></span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>const_cols, quasi_const_cols <span class="op">=</span> [], []</span></code></pre></div>\n</div>\n<div id="cell025" class="cell markdown">\n<h3 id="задание-42-пропуски-и-их-механизм">Задание 4.2. Пропуски и их\nмеханизм</h3>\n<p>Мало посчитать долю пропусков — важно понять, <strong>почему</strong>\nзначение отсутствует. Различают:</p>\n<ul>\n<li><strong>MCAR</strong> (missing completely at random) — пропуск не\nзависит ни от чего;</li>\n<li><strong>MAR</strong> (missing at random) — вероятность пропуска\nзависит от <em>других наблюдаемых</em> признаков (например, доход чаще\nне указывают клиенты с малым стажем);</li>\n<li><strong>MNAR</strong> — вероятность пропуска зависит от самого\nпропущенного значения (не указывают именно очень большие доходы). Худший\nслучай: по данным его не отличить.</li>\n</ul>\n<p>Постройте столбчатую диаграмму долей пропусков. Затем для каждого\nстолбца с пропусками проверьте гипотезу MAR: сравните средние значения\n<strong>остальных</strong> числовых признаков в группах «значение есть»\nи «значение пропущено». Если различия заметны — механизм не MCAR, и\nзаполнять пропуск средним по всей выборке опасно.</p>\n</div>\n<div id="cell026" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) горизонтальная столбчатая диаграмма долей пропусков по признакам</span></span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 2) для каждого столбца с пропусками — сравнение средних остальных</span></span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a><span class="co">#          числовых признаков в группах «есть значение» / «пропущено».</span></span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a><span class="co">#          Разницу удобно мерить в единицах стандартного отклонения признака.</span></span></code></pre></div>\n</div>\n<div id="cell027" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Для каких столбцов механизм пропусков похож\nна MCAR, а для каких — на MAR? Как это меняет способ заполнения?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell028" class="cell markdown">\n<h3 id="задание-43-выбросы">Задание 4.3. Выбросы</h3>\n<p>Два рабочих правила:</p>\n<ul>\n<li><strong>правило\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn><mi>σ</mi></mrow><annotation encoding="application/x-tex">3\\sigma</annotation></semantics></math></strong>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mi>x</mi><mo>−</mo><mover><mi>x</mi><mo accent="true">¯</mo></mover><mo stretchy="false" form="prefix">|</mo><mo>&gt;</mo><mn>3</mn><mi>σ</mi></mrow><annotation encoding="application/x-tex">|x - \\overline{x}| &gt; 3\\sigma</annotation></semantics></math>\n— годится для примерно нормальных признаков и само страдает от выбросов\n(они раздувают\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>σ</mi><annotation encoding="application/x-tex">\\sigma</annotation></semantics></math>);</li>\n<li><strong>правило межквартильного размаха</strong>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>&lt;</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>−</mo><mn>1</mn><mi>.</mi><mn>5</mn><mspace width="0.167em"></mspace><mrow><mi mathvariant="normal">I</mi><mi mathvariant="normal">Q</mi><mi mathvariant="normal">R</mi></mrow></mrow><annotation encoding="application/x-tex">x &lt; Q_1 - 1{.}5\\,\\mathrm{IQR}</annotation></semantics></math>\nили\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>&gt;</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>+</mo><mn>1</mn><mi>.</mi><mn>5</mn><mspace width="0.167em"></mspace><mrow><mi mathvariant="normal">I</mi><mi mathvariant="normal">Q</mi><mi mathvariant="normal">R</mi></mrow></mrow><annotation encoding="application/x-tex">x &gt; Q_3 + 1{.}5\\,\\mathrm{IQR}</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">I</mi><mi mathvariant="normal">Q</mi><mi mathvariant="normal">R</mi></mrow><mo>=</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub></mrow><annotation encoding="application/x-tex">\\mathrm{IQR} = Q_3 - Q_1</annotation></semantics></math>\n— устойчиво к самим выбросам.</li>\n</ul>\n<p>Постройте <code>boxplot</code> для числовых признаков (в\nстандартизованных единицах, иначе всё сольётся), посчитайте число\nвыбросов по обоим правилам и <strong>посмотрите на сами\nобъекты-выбросы</strong>: часть из них — опечатки (значение больше\nправдоподобного в 100 раз), часть — настоящие редкие объекты.</p>\n</div>\n<div id="cell029" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a>num_cols <span class="op">=</span> df.select_dtypes(include<span class="op">=</span><span class="st">&quot;number&quot;</span>).columns.drop(TARGET)</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) boxplot по стандартизованным числовым признакам</span></span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 2) таблица: число выбросов по правилу IQR и по правилу 3 sigma</span></span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 3) вывести сами объекты с самыми большими значениями подозрительного признака</span></span></code></pre></div>\n</div>\n<div id="cell030" class="cell markdown">\n<h3 id="задание-44-исправление-опечаток-масштаба">Задание 4.4.\nИсправление опечаток масштаба</h3>\n<p>Среди выбросов есть особая группа: значения, превышающие 99-й\nперцентиль примерно в 100 раз. Это не редкие объекты, а <strong>ошибка\nввода</strong> — потерянный десятичный разделитель (год\n<code>2010</code> записан как <code>201000</code>, пробег\n<code>85 000</code> как <code>8 500 000</code>).</p>\n<p>Найдите такие значения по правилу «больше 30 перцентилей\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>q</mi><mn>0.99</mn></msub><annotation encoding="application/x-tex">q_{0.99}</annotation></semantics></math>»,\nразделите их на 100 и покажите, как изменилась корреляция признака с\nцелевой переменной. Настоящие выбросы (превышение в 4–12 раз) не\nтрогайте: они правдоподобны.</p>\n</div>\n<div id="cell031" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждого числового признака найдите значения, превышающие 30 * q_{0.99},</span></span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       разделите их на 100 и сравните корреляцию признака с целью до и после.</span></span></code></pre></div>\n</div>\n<div id="cell032" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какое правило нашло больше выбросов и почему?\nКакие из найденных объектов — опечатки, а какие — настоящие редкие\nнаблюдения? Что вы с ними сделаете?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell033" class="cell markdown">\n<hr />\n<h1 id="часть-5-визуальный-анализ">Часть 5. Визуальный анализ</h1>\n<p>Три графика, которые стоит строить всегда: распределение каждого\nпризнака, распределение цели в разрезе категорий и матрица\nкорреляций.</p>\n</div>\n<div id="cell034" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>num_cols <span class="op">=</span> df.select_dtypes(include<span class="op">=</span><span class="st">&quot;number&quot;</span>).columns.drop(TARGET)</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a>cat_cols <span class="op">=</span> [c <span class="cf">for</span> c <span class="kw">in</span> meta[<span class="st">&quot;categorical&quot;</span>] <span class="cf">if</span> c <span class="kw">in</span> df.columns]</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (1) сетка гистограмм по числовым признакам</span></span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (2) распределение целевой переменной в разрезе каждого категориального</span></span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a><span class="co">#           признака (boxplot для регрессии, доля класса 1 для классификации)</span></span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (3) тепловая карта матрицы корреляций числовых признаков вместе с целью,</span></span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a><span class="co">#           и топ-5 признаков по |корреляции| с целью</span></span></code></pre></div>\n</div>\n<div id="cell035" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какие признаки сильнее всего связаны с целью?\nЕсть ли пары сильно коррелированных между собой признаков? Чем это\nгрозит?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell036" class="cell markdown">\n<hr />\n<h1 id="часть-6-ловушка-признак-которого-не-должно-быть">Часть 6.\nЛовушка: признак, которого не должно быть</h1>\n<p>В таблице есть столбец <code>id</code>. Формально это число, и его\nможно подать в модель. Проверьте, что будет.</p>\n</div>\n<div id="cell037" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> cross_val_score</span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.tree <span class="im">import</span> DecisionTreeClassifier, DecisionTreeRegressor</span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите решающее дерево ГЛУБИНЫ 4 на одном-единственном признаке id</span></span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       и оцените качество по 5-блочной кросс-валидации</span></span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       (r2 для регрессии, roc_auc для классификации).</span></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте диаграмму рассеяния &quot;id против цели&quot;.</span></span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: удалите столбец id из df.</span></span></code></pre></div>\n</div>\n<div id="cell038" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Откуда взялась такая связь и почему признак\n<code>id</code> необходимо удалить, хотя он улучшает качество?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell039" class="cell markdown">\n<hr />\n<h1 id="часть-7-разбиение-выборки-и-предобработка-без-утечек">Часть 7.\nРазбиение выборки и предобработка без утечек</h1>\n<p>Ключевое правило всего курса:</p>\n<blockquote>\n<p>Все параметры предобработки (средние, дисперсии, медианы для\nзаполнения пропусков, список категорий) вычисляются <strong>только по\nобучающей части</strong> и затем применяются к контрольной.</p>\n</blockquote>\n<p>Иначе информация о контрольной выборке просачивается в обучение, и\nоценка качества оказывается завышенной. Строгое обоснование — лекция 4 и\nработа 5, где мы измерим величину этого завышения.</p>\n<p>Технически это удобно делать через <code>Pipeline</code> и\n<code>ColumnTransformer</code>: они хранят параметры, подобранные на\n<code>fit</code>, и применяют их в <code>transform</code>.</p>\n</div>\n<div id="cell040" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.compose <span class="im">import</span> ColumnTransformer</span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.impute <span class="im">import</span> SimpleImputer</span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> OneHotEncoder, StandardScaler</span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a>X <span class="op">=</span> df.drop(columns<span class="op">=</span>[TARGET])</span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a>y <span class="op">=</span> df[TARGET]</span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-10"><a href="#cb16-10" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) разделите столбцы на числовые и категориальные</span></span>\n<span id="cb16-11"><a href="#cb16-11" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 2) train_test_split, test_size=0.25, random_state=RANDOM_STATE,</span></span>\n<span id="cb16-12"><a href="#cb16-12" aria-hidden="true" tabindex="-1"></a><span class="co">#          для классификации — со стратификацией по y</span></span>\n<span id="cb16-13"><a href="#cb16-13" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 3) соберите ColumnTransformer:</span></span>\n<span id="cb16-14"><a href="#cb16-14" aria-hidden="true" tabindex="-1"></a><span class="co">#          числовые   -&gt; SimpleImputer(median) + StandardScaler</span></span>\n<span id="cb16-15"><a href="#cb16-15" aria-hidden="true" tabindex="-1"></a><span class="co">#          категории  -&gt; SimpleImputer(most_frequent) + OneHotEncoder(handle_unknown=&quot;ignore&quot;)</span></span>\n<span id="cb16-16"><a href="#cb16-16" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 4) fit_transform на обучающей, transform на контрольной</span></span></code></pre></div>\n</div>\n<div id="cell041" class="cell markdown">\n<h3 id="задание-71-цена-нарушения-правила">Задание 7.1. Цена нарушения\nправила</h3>\n<p>Проверьте эмпирически, что порядок операций важен: вычислите среднее\nи стандартное отклонение признака (а) по всей выборке и (б) только по\nобучающей части. Насколько отличаются полученные стандартизованные\nзначения на контроле?</p>\n<p>Это «мягкая» утечка — она почти не портит качество, но именно она\nдаёт первое интуитивное понимание, зачем нужен <code>Pipeline</code>.\nКоличественную оценку ущерба от жёстких утечек мы получим в работе\n5.</p>\n</div>\n<div id="cell042" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb17"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb17-1"><a href="#cb17-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сравните стандартизацию контрольной части по статистикам всей выборки</span></span>\n<span id="cb17-2"><a href="#cb17-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       и по статистикам только обучающей части</span></span></code></pre></div>\n</div>\n<div id="cell043" class="cell markdown">\n<hr />\n<h1 id="часть-8-ориентир-с-чем-сравнивать-модели">Часть 8. Ориентир: с\nчем сравнивать модели</h1>\n<p>Прежде чем радоваться качеству модели, нужно знать, сколько даёт\n<strong>тривиальный ответ</strong>: константа. Для регрессии это среднее\n(оптимум для квадратичной ошибки) или медиана (оптимум для абсолютной);\nдля классификации — самый частый класс.</p>\n<p>Мера ошибки на этом этапе вводится «по определению» — строгое понятие\nфункции потерь и эмпирического риска появится на лекции 1:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">M</mi><mi mathvariant="normal">S</mi><mi mathvariant="normal">E</mi></mrow><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mo>,</mo><mspace width="2.0em"></mspace><mrow><mi mathvariant="normal">M</mi><mi mathvariant="normal">A</mi><mi mathvariant="normal">E</mi></mrow><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mo stretchy="false" form="prefix">|</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">|</mo><mo>,</mo><mspace width="2.0em"></mspace><msup><mi>R</mi><mn>2</mn></msup><mo>=</mo><mn>1</mn><mo>−</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><mo stretchy="false" form="prefix">(</mo><mover><mi>y</mi><mo accent="true">¯</mo></mover><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\mathrm{MSE} = \\frac1{\\ell}\\sum_{i=1}^{\\ell} (a(x_i) - y_i)^2, \\qquad\n\\mathrm{MAE} = \\frac1{\\ell}\\sum_{i=1}^{\\ell} |a(x_i) - y_i|, \\qquad\nR^2 = 1 - \\frac{\\sum_i (a(x_i) - y_i)^2}{\\sum_i (\\overline{y} - y_i)^2}.\n</annotation></semantics></math></p>\n<p>Заметьте:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">R^2 = 0</annotation></semantics></math>\n— это ровно качество константного прогноза средним.</p>\n</div>\n<div id="cell044" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb18"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb18-1"><a href="#cb18-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.dummy <span class="im">import</span> DummyClassifier, DummyRegressor</span>\n<span id="cb18-2"><a href="#cb18-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LinearRegression, LogisticRegression</span>\n<span id="cb18-3"><a href="#cb18-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> (accuracy_score, mean_absolute_error,</span>\n<span id="cb18-4"><a href="#cb18-4" aria-hidden="true" tabindex="-1"></a>                             mean_squared_error, r2_score, roc_auc_score)</span>\n<span id="cb18-5"><a href="#cb18-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb18-6"><a href="#cb18-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите на X_train_t два алгоритма и сравните их на контроле:</span></span>\n<span id="cb18-7"><a href="#cb18-7" aria-hidden="true" tabindex="-1"></a><span class="co">#   регрессия     : DummyRegressor(strategy=&#39;mean&#39;)  и LinearRegression</span></span>\n<span id="cb18-8"><a href="#cb18-8" aria-hidden="true" tabindex="-1"></a><span class="co">#                   метрики RMSE, MAE, R2</span></span>\n<span id="cb18-9"><a href="#cb18-9" aria-hidden="true" tabindex="-1"></a><span class="co">#   классификация : DummyClassifier(strategy=&#39;most_frequent&#39;) и LogisticRegression</span></span>\n<span id="cb18-10"><a href="#cb18-10" aria-hidden="true" tabindex="-1"></a><span class="co">#                   метрики accuracy, ROC-AUC</span></span>\n<span id="cb18-11"><a href="#cb18-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Результат оформите таблицей.</span></span></code></pre></div>\n</div>\n<div id="cell045" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько модель лучше константы? Что\nозначает <code>accuracy = 0.8</code> у константного классификатора, если\nклассы несбалансированы?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell046" class="cell markdown">\n<hr />\n<h1 id="часть-9-сохранение-результата">Часть 9. Сохранение\nрезультата</h1>\n<p>Подготовленные данные понадобятся в следующих работах. Сохраните:</p>\n<ul>\n<li>матрицы <code>X_train_t</code>, <code>X_test_t</code> и векторы\n<code>y_train</code>, <code>y_test</code> — в\n<code>data/prepared.npz</code>;</li>\n<li>очищенную таблицу до кодирования — в\n<code>data/clean.csv</code>;</li>\n<li>сам объект <code>preprocessor</code> — через <code>joblib</code>,\nчтобы применить его к новым данным.</li>\n</ul>\n</div>\n<div id="cell047" class="cell code">\n<div class="sourceCode" id="cb19"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb19-1"><a href="#cb19-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pathlib</span>\n<span id="cb19-2"><a href="#cb19-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> joblib</span>\n<span id="cb19-3"><a href="#cb19-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb19-4"><a href="#cb19-4" aria-hidden="true" tabindex="-1"></a>data_dir <span class="op">=</span> pathlib.Path(<span class="st">&quot;data&quot;</span>)</span>\n<span id="cb19-5"><a href="#cb19-5" aria-hidden="true" tabindex="-1"></a>data_dir.mkdir(exist_ok<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb19-6"><a href="#cb19-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb19-7"><a href="#cb19-7" aria-hidden="true" tabindex="-1"></a>np.savez_compressed(</span>\n<span id="cb19-8"><a href="#cb19-8" aria-hidden="true" tabindex="-1"></a>    data_dir <span class="op">/</span> <span class="st">&quot;prepared.npz&quot;</span>,</span>\n<span id="cb19-9"><a href="#cb19-9" aria-hidden="true" tabindex="-1"></a>    X_train<span class="op">=</span>X_train_t, X_test<span class="op">=</span>X_test_t,</span>\n<span id="cb19-10"><a href="#cb19-10" aria-hidden="true" tabindex="-1"></a>    y_train<span class="op">=</span>np.asarray(y_train), y_test<span class="op">=</span>np.asarray(y_test),</span>\n<span id="cb19-11"><a href="#cb19-11" aria-hidden="true" tabindex="-1"></a>    feature_names<span class="op">=</span>np.asarray(feature_names, dtype<span class="op">=</span><span class="bu">object</span>),</span>\n<span id="cb19-12"><a href="#cb19-12" aria-hidden="true" tabindex="-1"></a>)</span>\n<span id="cb19-13"><a href="#cb19-13" aria-hidden="true" tabindex="-1"></a>df.to_csv(data_dir <span class="op">/</span> <span class="st">&quot;clean.csv&quot;</span>, index<span class="op">=</span><span class="va">False</span>, encoding<span class="op">=</span><span class="st">&quot;utf-8&quot;</span>)</span>\n<span id="cb19-14"><a href="#cb19-14" aria-hidden="true" tabindex="-1"></a>joblib.dump(preprocessor, data_dir <span class="op">/</span> <span class="st">&quot;preprocessor.joblib&quot;</span>)</span>\n<span id="cb19-15"><a href="#cb19-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb19-16"><a href="#cb19-16" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;сохранено:&quot;</span>, <span class="op">*</span>[p.name <span class="cf">for</span> p <span class="kw">in</span> <span class="bu">sorted</span>(data_dir.iterdir())])</span></code></pre></div>\n</div>\n<div id="cell048" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Чем номинальный признак отличается от порядкового и почему их нельзя\nкодировать одинаково? Приведите пример из своей таблицы.</li>\n<li>Что такое утечка данных? Приведите два примера: один из вашей\nтаблицы, второй — придуманный для задачи «предсказать, вернёт ли клиент\nкредит».</li>\n<li>Почему параметры масштабирования нужно оценивать только по обучающей\nвыборке? Что именно завышается, если это правило нарушить?</li>\n<li>Правило\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn><mi>σ</mi></mrow><annotation encoding="application/x-tex">3\\sigma</annotation></semantics></math>\nнашло меньше выбросов, чем правило IQR. Объясните, почему так вышло,\nчерез определения обеих величин.</li>\n<li>Вы получили accuracy 0.93. Какие ещё два числа нужно знать, чтобы\nпонять, хороший это результат или нет?</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong>Заполнение пропусков с учётом механизма.</strong> Для\nстолбца, который вы определили как MAR, реализуйте два способа\nзаполнения: (а) общей медианой; (б) медианой внутри групп, заданных\nквартилями признака-драйвера. Сравните гистограммы заполненного признака\nс гистограммой на объектах без пропуска. Какой способ меньше искажает\nраспределение? Ответ подкрепите числом — расстоянием\nКолмогорова–Смирнова (<code>scipy.stats.ks_2samp</code>).</p></li>\n<li><p><strong>Своя реализация OneHotEncoder.</strong> Напишите функцию\n<code>one_hot(series, categories=None)</code>, которая возвращает\nматрицу индикаторов и список категорий; при <code>categories</code>,\nзаданном извне, неизвестные значения кодируются нулевой строкой.\nПроверьте совпадение со\n<code>sklearn.preprocessing.OneHotEncoder(handle_unknown=&#39;ignore&#39;)</code>\nна вашем категориальном признаке. Объясните, зачем нужен параметр\n<code>drop=&#39;first&#39;</code> и в каком случае его отсутствие ломает\nлинейную регрессию (подсказка: сумма индикаторов равна столбцу\nединиц).</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);